actions.script:
const edw = ec.entity.makeDataWriter()

// handle entityNames
if (!context.entityNames) {
    ec.message.addError(ec.l10n.localize("No entity names specified, not exporting anything."))
    return
}

if (typeof entityNames === 'string' && entityNames.includes(",")) {
    if (entityNames.startsWith("[")) entityNames = entityNames.substring(1)
    if (entityNames.endsWith("]")) entityNames = entityNames.substring(0, entityNames.length - 1)
    entityNames = entityNames.split(",")
}

if (Array.isArray(entityNames)) {
    for (const entityName of entityNames) {
        const entDef = ec.entity.getEntityDefinition(entityName)
        if (entDef == null) ec.message.addError(ec.resource.expand('Could not find entity with name ${entityName}',''))
    }
    edw.entityNames(entityNames)
} else {
    const entDef = ec.entity.getEntityDefinition(entityNames)
    if (entDef == null) ec.message.addError(ec.resource.expand('Could not find entity with name ${entityName}', '', {entityName: entityNames}))
    edw.entityName(String(entityNames))
}

if (ec.message.hasError()) return

if (dependentLevels) edw.dependentLevels(parseInt(dependentLevels, 10))
if (masterName) edw.master(masterName)
if (fromDate) edw.fromDate(ec.l10n.parseTimestamp(fromDate, null))
if (thruDate) edw.thruDate(ec.l10n.parseTimestamp(thruDate, null))
// a JavaScript object of field values ({statusId: 'X'}); Java's empty Groovy map, [:], is no filter
const filterText = String(filterMap || '').trim()
if (filterText && filterText != '[:]') {
    const filter = ec.resource.expression('(' + filterText + ')', null)
    if (filter == null || typeof filter != 'object' || Array.isArray(filter)) {
        ec.message.addError(ec.l10n.localize("The filter is not an object of field values, such as {statusId: 'X'}"))
        return
    }
    edw.filterMap(filter)
}
if (orderBy) edw.orderBy([String(orderBy)])
edw.fileType(String(fileType))
if(fileType == 'CSV') edw.tableColumnNames(useTableColumnNames == 'Yes' ? true : false)

noResponse = false
if (context.output == "file") {
    edw.file(path)
} else if (context.output == "dir") {
    edw.directory(path)
} else if (context.output == "browser") {
    // The data writer has no writer(Writer): it answers the text, which is sent as a download
    const stamp = ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')
    if (fileType == 'CSV' && Array.isArray(entityNames) && entityNames.length > 1) {
        // more than one entity as CSV is a zip with a file for each, written to the user's own
        // temporary place and sent from there; the user's earlier ones are removed first (the
        // response reads the file after these actions, so this one stays until the next export)
        const place = `tmp/entity-export/${ec.user.userId}`
        const placeRef = ec.resource.getLocationReference('runtime://' + place)
        if (placeRef.getExists()) for (const earlier of placeRef.getDirectoryEntries()) {
            try { if (!earlier.isDirectory()) earlier.delete() }
            catch (error) { ec.logger.error('Entity export: could not remove ' + earlier.fileName + ': ' + String(error)) }
        }
        const within = `${place}/EntityExport_${stamp}_${Date.now()}.zip`
        edw.zipDirectory('', ec.factory.getRuntimePath() + '/' + within)
        if (!ec.message.hasError()) {
            if (ec.resource.getLocationReference('runtime://' + within).getExists()) {
                ec.web.sendResourceResponse('runtime://' + within, false, `EntityExport_${stamp}.zip`)
            } else {
                ec.message.addError(ec.l10n.localize("The export zip was not written"))
            }
        }
    } else {
        const text = edw.text()
        if (!ec.message.hasError()) ec.web.sendTextResponse(text,
            fileType == 'JSON' ? 'application/json' : fileType == 'CSV' ? 'text/csv' : 'text/xml',
            `EntityExport_${stamp}.${fileType == 'JSON' ? 'json' : fileType == 'CSV' ? 'csv' : 'xml'}`)
    }
    if (ec.message.hasError()) return
    ec.web.response.setHeader("Cache-Control", "no-cache, must-revalidate, private")
    noResponse = true
}

if (!context.dataDocumentIds) {
    ec.message.addError(ec.l10n.localize("No Data Documents specified, not exporting anything."))
    return
}
const edd = ec.entity.getEntityDataDocument()
const prettyPrint = String(context.prettyPrint) == 'true'
fromUpdateStamp = fromUpdateStamp ? ec.l10n.parseTimestamp(fromUpdateStamp, null) : null
thruUpdateStamp = thruUpdateStamp ? ec.l10n.parseTimestamp(thruUpdateStamp, null) : null

const dataDocumentIdList = (typeof dataDocumentIds === 'string') ? [dataDocumentIds] : dataDocumentIds
noResponse = false
if (context.output == "file") {
    edd.writeDocumentsToFile(String(path), dataDocumentIdList, null,
            fromUpdateStamp, thruUpdateStamp, prettyPrint)
} else if (context.output == "dir") {
    edd.writeDocumentsToDirectory(String(path), dataDocumentIdList, null,
            fromUpdateStamp, thruUpdateStamp, prettyPrint)
} else {
    const response = ec.web.response
    response.setContentType("application/json")
    response.setCharacterEncoding("UTF-8")
    response.setHeader("Cache-Control", "no-cache, must-revalidate, private")
    response.getWriter().write("[\n")
    edd.writeDocumentsToWriter(response.getWriter(), dataDocumentIdList, null,
            fromUpdateStamp, thruUpdateStamp, prettyPrint)
    response.getWriter().write("]\n")
    noResponse = true
}
